    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable {
        require(address(c).balance >= amount);
        uint balBefore = address(c).balance;
        uint cntBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.withdraw(amount); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore - amount && c.depositsCount() == cntBefore);
    }
    receive() external payable {}
}

