pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.assume(address(c).balance >= amount);
        uint balBefore = address(c).balance;
        uint256 cntBefore;
        try c.depositsCount() returns (uint256 __r) { cntBefore = __r; } catch { return; }
        try c.withdraw(amount) {} catch { return; }
        assertTrue(address(c).balance == balBefore - amount && c.depositsCount() == cntBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
